import{z as o,x as C,o as B,c as s,q as r,j as i,D as a,d as e,s as t,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"气候金融","description":"","frontmatter":{"title":"气候金融","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/env-climate-finance.md","filePath":"econ/env-climate-finance.md","lastUpdated":1791413859000}'),d={name:"econ/env-climate-finance.md"};function D(p,E,c,m,h,f){const n=C("Mermaid");return B(),s("div",null,[E[2]||(E[2]=r('<h1 id="气候金融" tabindex="-1">气候金融 <a class="header-anchor" href="#气候金融" aria-label="Permalink to &quot;气候金融&quot;">​</a></h1><div class="epigraph"><p>转型是提前花的资本开支：技术决定度电成本的下限，贴现率决定谁能等到那一天。</p><footer>—— 据 Nordhaus 2017 的贴现口径与 TCFD 2017 年披露建议整理</footer></div><p><a href="/econ/env-subsidy-design">上一课</a>给补贴立了账本：补哪个失灵、何时退、谁搭了便车。账本往下追问一层就是金融：转型是先花几十年资本开支、后收几十年损害减少——谁来垫资、按什么利率垫，常常比技术本身更决定项目生死。贴现率的伦理之争在 <a href="/econ/pigouvian-carbon-price">庇古税与碳定价</a> 已读，本课把它换成资本成本口径，写气候怎样被写进资产负债表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>转型资金有两个特征。前重后轻：资本开支前置、现金流长而薄，对融资成本极端敏感——同一座电站，融资成本差两三个百分点，度电成本差出一截；政策反复等于给所有绿色资产加风险溢价，<a href="/econ/env-energy-transition">能源转型经济学</a>的期权逻辑在此变成 WACC。风险错配：气候损害与转型风险落在没有定价话语的主体——未来世代、发展中国家；公共资金的可信度本身是金融变量：发达国家 2009 年承诺每年动员 1000 亿美元气候资金，OECD 口径到 2022 年才首次兑现。缺口因此是：给全球量级的投资需求，找到能落地的风险定价与风险分担结构。</p><p><span class="marginnote">数字实例：绿色电站的成本大头在前期资本开支。融资成本若从 5% 升到 10%，同样一座电站的度电成本能贵出五成上下——设备与技术一模一样，变的只是「钱有多贵」。这就是「前重后轻」把 WACC 当生死线的含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个杠杆。披露：TCFD（2017 年建议）把治理、战略、风险管理、指标四支柱做成报告口径，分类法给「绿色」下可核验的定义——信息先于定价，不可见的风险不可定价。风险分担：混合金融用优惠资本做第一损失层，改写项目的风险收益轮廓，直到机构资本进得来——目标不是压名义成本，是压加权平均资本成本。工具化：绿色债券锁定用途并要求报告（欧洲投资银行 2007 年首只气候意识债券起步）；碳拍卖收入与国际转让把碳价变成资金流；搁浅资产风险从学术口径进入信用分析（Carbon Tracker 2011 的不可燃碳估算），央行网络 NGFS（2017 年成立）把气候情景做成压力测试条目。</p>',8)),(B(),i(l,null,{default:a(()=>[t(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E8%BD%AC%E5%9E%8B%E8%B5%84%E6%9C%AC%3A%20%E5%89%8D%E9%87%8D%E5%90%8E%E8%BD%BB%22%5D%20--%3E%20WACC%5B%22%E5%AF%B9%E8%9E%8D%E8%B5%84%E6%88%90%E6%9C%AC%E6%9E%81%E7%AB%AF%E6%95%8F%E6%84%9F%22%5D%0A%20%20WACC%20--%3E%20LEV%7B%22%E4%B8%89%E4%B8%AA%E6%9D%A0%E6%9D%86%22%7D%0A%20%20LEV%20--%3E%7C%E6%8A%AB%E9%9C%B2%7C%20DISC%5B%22TCFD%20%E4%B8%8E%E5%88%86%E7%B1%BB%E6%B3%95%3A%20%E9%A3%8E%E9%99%A9%E5%8F%AF%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20LEV%20--%3E%7C%E5%88%86%E6%8B%85%7C%20BLEND%5B%22%E6%B7%B7%E5%90%88%E9%87%91%E8%9E%8D%3A%20%E4%BC%98%E6%83%A0%E5%B1%82%E5%8E%8B%20WACC%22%5D%0A%20%20LEV%20--%3E%7C%E5%B7%A5%E5%85%B7%7C%20BOND%5B%22%E7%BB%BF%E8%89%B2%E5%80%BA%E5%88%B8%E4%B8%8E%E7%A2%B3%E5%B8%82%E5%9C%BA%E8%B5%84%E9%87%91%E6%B5%81%22%5D%0A%20%20STRAND%5B%22%E6%90%81%E6%B5%85%E8%B5%84%E4%BA%A7%E9%A3%8E%E9%99%A9%22%5D%20--%3E%20DISC%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"披露为什么是定价的前置：气候风险原本是所有组合的共同噪声，价格无法区分好坏持仓；披露让风险可比较、可交易，资本才开始向低风险者集中。混合金融为什么动 WACC 而非名义成本：回报按资本结构分层，优惠层吸收首损，商业层的风险溢价随之下降——同一笔优惠预算，垫在资本结构里比贴在电价上撬动更多资本。搁浅资产为什么是系统问题而非公司问题：碳预算收紧使减记集中在少数资产负债表上，一致预期的突然反转才是监管者担心的形态——个体理性（先卖）合成集体踩踏。",-1)),(B(),i(l,null,{default:a(()=>[t(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROJ%5B%22%E4%B8%80%E4%B8%AA%E7%BB%BF%E8%89%B2%E7%94%B5%E7%AB%99%E9%A1%B9%E7%9B%AE%22%5D%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%E7%BB%93%E6%9E%84%E5%88%86%E5%B1%82%22%5D%0A%20%20CAP%20--%3E%20L1%5B%22%E7%AC%AC%E4%B8%80%E6%8D%9F%E5%A4%B1%E5%B1%82%EF%BC%9A%E4%BC%98%E6%83%A0%E8%B5%84%E6%9C%AC%20%2F%20%E6%8B%85%E4%BF%9D%EF%BC%88%E5%85%88%E4%BA%8F%E3%80%81%E4%BD%8E%E5%9B%9E%E6%8A%A5%EF%BC%89%22%5D%0A%20%20CAP%20--%3E%20L2%5B%22%E5%95%86%E4%B8%9A%E5%B1%82%EF%BC%9A%E6%9C%BA%E6%9E%84%E8%B5%84%E6%9C%AC%EF%BC%88%E6%80%95%E9%A6%96%E6%8D%9F%E3%80%81%E8%A6%81%E6%BA%A2%E4%BB%B7%EF%BC%89%22%5D%0A%20%20L1%20--%3E%20ABS%5B%22%E9%A6%96%E6%8D%9F%E8%A2%AB%E4%BC%98%E6%83%A0%E5%B1%82%E5%90%B8%E6%94%B6%22%5D%0A%20%20L2%20--%3E%20ABS%0A%20%20ABS%20--%3E%20LOW%5B%22%E5%95%86%E4%B8%9A%E5%B1%82%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%E4%B8%8B%E9%99%8D%20%E2%86%92%20WACC%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LOW%20--%3E%20MORE%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E4%BC%98%E6%83%A0%E9%A2%84%E7%AE%97%E6%92%AC%E5%8A%A8%E6%95%B0%E5%80%8D%E7%9A%84%E7%A7%81%E4%BA%BA%E8%B5%84%E6%9C%AC%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">术语翻译：WACC（加权平均资本成本）就是「项目借各种钱所付利率的加权平均」。混合金融不是把利息贴低，而是让优惠的钱先扛亏损——商业资本看到首损有人垫，要的溢价就小，加权平均自然降下来。</span></p><p><span class="marginnote">OECD 口径：发达国家动员的气候资金 2022 年首次越过 1000 亿美元线（约 1159 亿）——从承诺到兑现十三年；对融资成本敏感的项目，承诺的可信度本身就是补贴。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「绿色」标签的可核验性有限，漂绿是分类法要长期治的病。额外性原则上可定义、实操上难验证：「没有这笔钱项目就做不成」的反事实不可观测。担保与优惠资金带来道德风险，适应资金长期落后于减缓。贴现率的伦理没有技术答案，只有明示假设的纪律。气候金融不是第二财政：它能改风险的分布与时间形态，改不了损害函数的形状；把金融工具当成减排本身，是这一课最贵的误会。</p><p><span class="marginnote">常见误区：以为「发绿色债券 = 减排」。债券锁定的只是资金用途，减没减排取决于项目本身真的少烧了多少碳。金融工具能改风险的分布与时间形态，改不了损害函数——把融资包装当成减排量，是这一课最贵的误会。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>转型资金前重后轻：融资成本与政策可信度是项目生死的一阶变量。</li><li>信息先于定价：披露与分类法把气候风险从共同噪声变成可交易的信息。</li><li>混合金融压的是 WACC：优惠层做首损，同一预算撬动更多资本。</li><li>工具化渠道：绿色债券锁用途，碳价收入与国际转让把碳价变成资金流。</li><li>搁浅资产从公司问题变成系统问题，靠披露与情景测试提前显影。</li><li>出处：TCFD 2017；Carbon Tracker 2011；OECD 气候资金口径；EIB 2007。</li></ul>',7))])}const _=o(d,[["render",D]]);export{F as __pageData,_ as default};
